<?php
require_once __DIR__.'/../global.php';
require_admin();
$tabs=['overview'=>'Tổng quan','products'=>'Sản phẩm & tồn kho','categories'=>'Danh mục','orders'=>'Đơn hàng','customers'=>'Khách hàng','feedback'=>'Phản hồi'];
$tab=(string)($_GET['tab']??'overview');if(!isset($tabs[$tab]))$tab='overview';
$notice='';$today=date('Y-m-d');$from=(string)($_GET['from']??date('Y-m-01'));$to=(string)($_GET['to']??$today);
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to=$today;
try{
 if($_SERVER['REQUEST_METHOD']==='POST'){
  check_csrf();$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);
  if($action==='save_category'){$name=trim((string)($_POST['name']??''));$slug=trim((string)($_POST['slug']??''));$desc=trim((string)($_POST['description']??''));if(!$name||!preg_match('/^[a-z0-9-]+$/',$slug))throw new DomainException('Tên hoặc slug danh mục chưa hợp lệ.');if($id){$s=$conn->prepare('UPDATE categories SET name=?,slug=?,description=? WHERE id=?');$s->bind_param('sssi',$name,$slug,$desc,$id);}else{$s=$conn->prepare('INSERT INTO categories(name,slug,description) VALUES(?,?,?)');$s->bind_param('sss',$name,$slug,$desc);}$s->execute();
  }elseif($action==='category_toggle'){$s=$conn->prepare('UPDATE categories SET is_active=1-is_active WHERE id=?');$s->bind_param('i',$id);$s->execute();
  }elseif($action==='save_product'){$name=trim((string)($_POST['name']??''));$cid=(int)($_POST['category_id']??0);$desc=trim((string)($_POST['description']??''));$price=(float)($_POST['price']??0);$stock=(int)($_POST['stock']??-1);$image=trim((string)($_POST['image_url']??''));$featured=isset($_POST['is_featured'])?1:0;if(!$name||$cid<1||$price<0||$stock<0||($image&&(!filter_var($image,FILTER_VALIDATE_URL)||!in_array(strtolower((string)parse_url($image,PHP_URL_SCHEME)),['http','https'],true))))throw new DomainException('Thông tin sản phẩm chưa hợp lệ.');if($id){$s=$conn->prepare('UPDATE products SET category_id=?,name=?,description=?,price=?,image_url=?,stock=?,is_featured=? WHERE id=?');$s->bind_param('issdsiii',$cid,$name,$desc,$price,$image,$stock,$featured,$id);}else{$s=$conn->prepare('INSERT INTO products(category_id,name,description,price,image_url,stock,is_featured) VALUES(?,?,?,?,?,?,?)');$s->bind_param('issdsii',$cid,$name,$desc,$price,$image,$stock,$featured);}$s->execute();
  }elseif($action==='product_toggle'){$s=$conn->prepare('UPDATE products SET is_active=1-is_active WHERE id=?');$s->bind_param('i',$id);$s->execute();
  }elseif($action==='order_status'){$status=(string)($_POST['status']??'');$valid=['pending','confirmed','preparing','shipping','completed','cancelled'];if(!in_array($status,$valid,true))throw new DomainException('Trạng thái đơn không hợp lệ.');$conn->begin_transaction();try{$q=$conn->prepare('SELECT status FROM orders WHERE id=? FOR UPDATE');$q->bind_param('i',$id);$q->execute();$old=$q->get_result()->fetch_assoc();if(!$old)throw new DomainException('Không tìm thấy đơn hàng.');if($old['status']!==$status){$items=$conn->prepare('SELECT product_id,quantity FROM order_items WHERE order_id=?');$items->bind_param('i',$id);$items->execute();$rows=$items->get_result()->fetch_all(MYSQLI_ASSOC);$items->close();if($status==='cancelled'&&$old['status']!=='cancelled'){$up=$conn->prepare('UPDATE products SET stock=stock+? WHERE id=?');foreach($rows as $r)if($r['product_id']){$qty=(int)$r['quantity'];$pid=(int)$r['product_id'];$up->bind_param('ii',$qty,$pid);$up->execute();}}elseif($old['status']==='cancelled'&&$status!=='cancelled'){$up=$conn->prepare('UPDATE products SET stock=stock-? WHERE id=? AND stock>=?');foreach($rows as $r)if($r['product_id']){$qty=(int)$r['quantity'];$pid=(int)$r['product_id'];$up->bind_param('iii',$qty,$pid,$qty);$up->execute();if($up->affected_rows!==1)throw new DomainException('Tồn kho không đủ để mở lại đơn này.');}}$up=$conn->prepare('UPDATE orders SET status=? WHERE id=?');$up->bind_param('si',$status,$id);$up->execute();}$conn->commit();}catch(Throwable $e){$conn->rollback();throw $e;}
  }elseif($action==='payment_confirm'){$s=$conn->prepare("UPDATE orders SET payment_status='paid',payment_confirmed_at=NOW() WHERE id=? AND payment_status IN ('reported','unpaid')");$s->bind_param('i',$id);$s->execute();
  }elseif($action==='feedback_delete'){$s=$conn->prepare('DELETE FROM feedback WHERE id=?');$s->bind_param('i',$id);$s->execute();
  }else throw new DomainException('Thao tác không hợp lệ.');
  header('Location: index.php?tab='.urlencode($tab).'&saved=1');exit;
 }
}catch(Throwable $e){$notice=$e instanceof DomainException?$e->getMessage():'Không lưu được. Có thể dữ liệu đang được sử dụng hoặc bị trùng.';}
$cats=$conn->query('SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.sort_order,c.name')->fetch_all(MYSQLI_ASSOC);
$products=$conn->query('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.is_active DESC,p.name')->fetch_all(MYSQLI_ASSOC);
$orders=$conn->query('SELECT * FROM orders ORDER BY created_at DESC LIMIT 150')->fetch_all(MYSQLI_ASSOC);
$customers=$conn->query("SELECT id,fullname,email,phone,role,gender,birth_date,created_at FROM users ORDER BY role='admin' DESC,id DESC LIMIT 200")->fetch_all(MYSQLI_ASSOC);
$feedback=$conn->query('SELECT * FROM feedback ORDER BY created_at DESC LIMIT 150')->fetch_all(MYSQLI_ASSOC);
$editId=(int)($_GET['edit']??0);$editing=null;if($tab==='products'){foreach($products as $r)if((int)$r['id']===$editId){$editing=$r;break;}}elseif($tab==='categories'){foreach($cats as $r)if((int)$r['id']===$editId){$editing=$r;break;}}
$fromSql=$conn->real_escape_string($from);$toSql=$conn->real_escape_string($to);
$revenue=(float)$conn->query("SELECT COALESCE(SUM(total),0) v FROM orders WHERE payment_status='paid' AND status<>'cancelled' AND DATE(created_at) BETWEEN '$fromSql' AND '$toSql'")->fetch_assoc()['v'];
$orderCount=(int)$conn->query("SELECT COUNT(*) n FROM orders WHERE DATE(created_at) BETWEEN '$fromSql' AND '$toSql'")->fetch_assoc()['n'];
$pendingCount=(int)$conn->query("SELECT COUNT(*) n FROM orders WHERE status IN ('pending','confirmed','preparing','shipping')")->fetch_assoc()['n'];
$lowStock=(int)$conn->query('SELECT COUNT(*) n FROM products WHERE is_active=1 AND stock<5')->fetch_assoc()['n'];
$daily=$conn->query("SELECT DATE(created_at) d,COALESCE(SUM(CASE WHEN payment_status='paid' AND status<>'cancelled' THEN total ELSE 0 END),0) revenue,COUNT(*) orders FROM orders WHERE DATE(created_at) BETWEEN '$fromSql' AND '$toSql' GROUP BY DATE(created_at) ORDER BY d")->fetch_all(MYSQLI_ASSOC);
$categoryCounts=$conn->query('SELECT c.name,COUNT(p.id) total FROM categories c LEFT JOIN products p ON p.category_id=c.id AND p.is_active=1 GROUP BY c.id ORDER BY c.sort_order')->fetch_all(MYSQLI_ASSOC);
function admin_money($x):string{return number_format((float)$x,0,',','.').'₫';}
function admin_status($s):string{return ['pending'=>'Chờ xác nhận','confirmed'=>'Đã xác nhận','preparing'=>'Đang chuẩn bị','shipping'=>'Đang giao','completed'=>'Hoàn tất','cancelled'=>'Đã hủy'][$s]??$s;}
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quản trị · Cà phê Hoàng</title><link rel="stylesheet" href="../css/hoang-cafe.css?v=2"><style>.admin-content{max-width:1420px;margin:28px auto;padding:0 24px}.admin-table{overflow:auto}.admin-table table{min-width:850px}.admin-title{display:flex;justify-content:space-between;align-items:center;gap:18px}.admin-title h1{font:600 34px 'Playfair Display',serif;margin:3px 0}.admin-cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.admin-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.admin-form-grid label{display:block;font-size:12px;margin:8px 0}.admin-form-grid input,.admin-form-grid select,.admin-form-grid textarea{display:block;width:100%;padding:10px;border:1px solid var(--line);border-radius:8px;margin-top:6px}.admin-actions{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.admin-actions form{margin:0}.admin-actions button{white-space:nowrap}.admin-nav{border-bottom:1px solid var(--line);padding-bottom:12px}.admin-nav a{padding:10px 13px}.status-pill{display:inline-block;padding:5px 8px;border-radius:99px;background:#f4eadc;font-size:11px}.status-pill.good{background:#e5f0e1;color:#42623e}.status-pill.low{background:#fff0d8;color:#996116}.chart{height:260px;width:100%;background:linear-gradient(180deg,#fff,#fcf8f2);border:1px solid var(--line);border-radius:12px}.filters{display:flex;gap:8px;align-items:end;flex-wrap:wrap}.filters label{font-size:11px}.filters input{display:block;padding:9px;border:1px solid var(--line);border-radius:8px;margin-top:5px}.table-thumb{width:54px;height:44px;border-radius:6px;object-fit:cover}.hint{color:var(--muted);font-size:12px}@media(max-width:760px){.admin-cards{grid-template-columns:repeat(2,minmax(0,1fr))}.admin-title{align-items:flex-start;flex-direction:column}.admin-content{padding:0 13px}.admin-form-grid{grid-template-columns:1fr}}</style></head><body><header class="admin-header"><a class="brand footer-brand" href="../index.php"><span class="brand-mark">H</span><span><strong>HOÀNG CAFE</strong><small>QUẢN TRỊ CỬA HÀNG</small></span></a><div>Xin chào <?=h(user()['fullname']??'Chủ quán')?> · <a href="../index.php">Xem cửa hàng ↗</a></div></header><main class="admin-content"><div class="admin-title"><div><span class="eyebrow">HOÀNG CAFE · KHU VỰC CHỦ QUÁN</span><h1><?=h($tabs[$tab])?></h1><p class="hint">Quản lý thực đơn, giá bán, tồn kho, đơn hàng và khách hàng trong cùng một bảng điều khiển.</p></div><?php if($tab==='products'):?><a class="button" href="?tab=products#product-form">+ Thêm món</a><?php endif;?></div><nav class="admin-nav"><?php foreach($tabs as $key=>$label):?><a class="<?=$tab===$key?'active':''?>" href="?tab=<?=h($key)?>"><?=h($label)?></a><?php endforeach;?></nav><?php if($notice):?><p class="error"><?=h($notice)?></p><?php elseif(isset($_GET['saved'])):?><p class="notice">Đã lưu thay đổi.</p><?php endif;?>
<?php if($tab==='overview'):?><section class="admin-card"><form class="filters" method="get"><input type="hidden" name="tab" value="overview"><label>Từ ngày<input type="date" name="from" value="<?=h($from)?>"></label><label>Đến ngày<input type="date" name="to" value="<?=h($to)?>"></label><button class="button button-sm">Lọc doanh thu</button><a class="text-link" href="?tab=overview">Tháng này</a></form></section><section class="admin-cards"><article class="metric"><span>Doanh thu đã nhận</span><strong><?=admin_money($revenue)?></strong><small><?=h(date('d/m/Y',strtotime($from)))?> – <?=h(date('d/m/Y',strtotime($to)))?></small></article><article class="metric"><span>Đơn trong khoảng ngày</span><strong><?=$orderCount?></strong><small>Đơn hàng đã tạo</small></article><article class="metric"><span>Đơn đang xử lý</span><strong><?=$pendingCount?></strong><small>Chờ xác nhận, chuẩn bị hoặc giao</small></article><article class="metric"><span>Món sắp hết</span><strong><?=$lowStock?></strong><small>Tồn kho dưới 5 phần</small></article></section><section class="admin-card"><h2>Doanh thu theo ngày</h2><?php if(!$daily):?><p class="hint">Chưa có dữ liệu trong khoảng ngày này.</p><?php else:?><canvas class="chart" id="revenueChart" aria-label="Biểu đồ doanh thu theo ngày"></canvas><script>const sales=<?=json_encode($daily,JSON_UNESCAPED_UNICODE)?>;const cv=document.getElementById('revenueChart'),cx=cv.getContext('2d');function draw(){const dpr=devicePixelRatio||1;cv.width=cv.clientWidth*dpr;cv.height=cv.clientHeight*dpr;cx.scale(dpr,dpr);const w=cv.clientWidth,h=cv.clientHeight,p={l:58,r:18,t:18,b:42},max=Math.max(1,...sales.map(x=>Number(x.revenue))),step=(w-p.l-p.r)/Math.max(1,sales.length-1);cx.strokeStyle='#e8dfd3';cx.fillStyle='#77736b';cx.font='11px Arial';for(let i=0;i<=4;i++){const y=p.t+(h-p.t-p.b)*i/4;cx.beginPath();cx.moveTo(p.l,y);cx.lineTo(w-p.r,y);cx.stroke();cx.fillText(Math.round(max*(4-i)/4/1000)+'k',8,y+4)}cx.strokeStyle='#bd4d32';cx.lineWidth=3;cx.beginPath();sales.forEach((x,i)=>{const px=p.l+step*i,py=h-p.b-Number(x.revenue)/max*(h-p.t-p.b);i?cx.lineTo(px,py):cx.moveTo(px,py)});cx.stroke();sales.forEach((x,i)=>{const px=p.l+step*i,py=h-p.b-Number(x.revenue)/max*(h-p.t-p.b);cx.fillStyle='#bd4d32';cx.beginPath();cx.arc(px,py,4,0,Math.PI*2);cx.fill();if(sales.length<18||i%Math.ceil(sales.length/12)===0){cx.fillStyle='#77736b';cx.fillText(x.d.slice(5),px-16,h-14)}})}draw();addEventListener('resize',draw);</script><?php endif;?></section><section class="admin-cards"><article class="admin-card"><h2>Đơn hàng gần đây</h2><a class="text-link" href="?tab=orders">Xem tất cả ↗</a><?php foreach(array_slice($orders,0,5) as $o):?><p><b><?=h($o['code'])?></b> · <?=admin_money($o['total'])?><br><span class="hint"><?=h(admin_status($o['status']))?> · <?=h(date('d/m H:i',strtotime($o['created_at'])))?></span></p><?php endforeach;?></article><article class="admin-card"><h2>Danh mục & tình trạng món</h2><?php foreach($categoryCounts as $c):?><p><?=h($c['name'])?><span style="float:right"><?=h($c['total'])?> món</span></p><?php endforeach;?></article></section>
<?php elseif($tab==='products'):?><section class="admin-card" id="product-form"><h2><?=$editing?'Chỉnh sửa món':'Thêm món mới'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save_product"><input type="hidden" name="id" value="<?=h($editing['id']??0)?>"><div class="admin-form-grid"><label>Tên món<input required name="name" value="<?=h($editing['name']??'')?>"></label><label>Danh mục<select required name="category_id"><?php foreach($cats as $c):if(!$c['is_active']&&($editing['category_id']??0)!=$c['id'])continue;?><option value="<?=$c['id']?>" <?=($editing['category_id']??0)==$c['id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach;?></select></label><label>Giá bán (₫)<input required type="number" min="0" step="1000" name="price" value="<?=h($editing['price']??0)?>"></label><label>Số lượng trong kho<input required type="number" min="0" name="stock" value="<?=h($editing['stock']??20)?>"></label><label class="full">URL ảnh (có thể dán link ảnh trực tiếp)<input type="url" name="image_url" value="<?=h($editing['image_url']??'')?>"></label><label class="full">Mô tả<textarea name="description" rows="3"><?=h($editing['description']??'')?></textarea></label><label><input type="checkbox" name="is_featured" value="1" <?=!empty($editing['is_featured'])?'checked':''?>> Đưa lên món nổi bật</label></div><button class="button"><?=$editing?'Lưu chỉnh sửa':'Thêm món'?></button><?php if($editing):?> <a class="button button-outline" href="?tab=products">Hủy sửa</a><?php endif;?></form></section><section class="admin-card admin-table"><h2>Thực đơn & tồn kho <span class="hint">· Trạng thái tự động: dưới 5 là sắp hết</span></h2><table><tr><th>Món</th><th>Danh mục</th><th>Giá</th><th>Tồn kho</th><th>Trạng thái</th><th>Thao tác</th></tr><?php foreach($products as $p):?><tr><td><div class="admin-product"><img class="table-thumb" src="<?=h(image_url($p['image_url']))?>" alt=""><div><b><?=h($p['name'])?></b><br><small><?=h($p['description'])?></small></div></div></td><td><?=h($p['category_name'])?></td><td><?=admin_money($p['price'])?></td><td><?=h($p['stock'])?> phần</td><td><span class="status-pill <?=$p['stock']<5?'low':'good'?>"><?=$p['stock']<1?'Hết món':($p['stock']<5?'Sắp hết':'Còn hàng')?></span><?=!$p['is_active']?' · Đang ẩn':''?></td><td><div class="admin-actions"><a class="button button-sm button-outline" href="?tab=products&edit=<?=$p['id']?>#product-form">Sửa</a><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="product_toggle"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="button button-sm <?=!$p['is_active']?'':'danger-button'?>"><?=$p['is_active']?'Ẩn':'Hiện lại'?></button></form></div></td></tr><?php endforeach;?></table></section>
<?php elseif($tab==='categories'):?><section class="admin-card"><h2><?=$editing?'Sửa danh mục':'Thêm danh mục'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save_category"><input type="hidden" name="id" value="<?=h($editing['id']??0)?>"><div class="admin-form-grid"><label>Tên danh mục<input required name="name" value="<?=h($editing['name']??'')?>"></label><label>Slug không dấu<input required pattern="[a-z0-9-]+" name="slug" value="<?=h($editing['slug']??'')?>"></label><label class="full">Mô tả<textarea name="description"><?=h($editing['description']??'')?></textarea></label></div><button class="button">Lưu danh mục</button></form></section><section class="admin-card admin-table"><table><tr><th>Danh mục</th><th>Mô tả</th><th>Số món</th><th>Trạng thái</th><th>Thao tác</th></tr><?php foreach($cats as $c):?><tr><td><?=h($c['name'])?></td><td><?=h($c['description'])?></td><td><?=$c['product_count']?></td><td><span class="status-pill <?=$c['is_active']?'good':'low'?>"><?=$c['is_active']?'Đang hiện':'Đang ẩn'?></span></td><td><div class="admin-actions"><a class="button button-sm button-outline" href="?tab=categories&edit=<?=$c['id']?>">Sửa</a><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="category_toggle"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="button button-sm"><?=$c['is_active']?'Ẩn':'Hiện lại'?></button></form></div></td></tr><?php endforeach;?></table></section>
<?php elseif($tab==='orders'):?><section class="admin-card admin-table"><h2>Đơn hàng mới nhất</h2><table><tr><th>Mã đơn / thời gian</th><th>Khách hàng</th><th>Món</th><th>Tổng tiền</th><th>Thanh toán</th><th>Trạng thái đơn</th></tr><?php foreach($orders as $o):?><tr><td><b><?=h($o['code'])?></b><br><small><?=h(date('d/m/Y H:i',strtotime($o['created_at'])))?></small></td><td><?=h($o['customer_name'])?><br><?=h($o['phone'])?><br><small><?=h($o['address'])?></small></td><td><?php $it=$conn->prepare('SELECT product_name,quantity FROM order_items WHERE order_id=?');$it->bind_param('i',$o['id']);$it->execute();foreach($it->get_result() as $item)echo h($item['product_name']).' × '.h($item['quantity']).'<br>';?></td><td><?=admin_money($o['total'])?></td><td><?=h($o['payment_method']==='bank_transfer'?'Chuyển khoản':'Tiền mặt')?><br><span class="status-pill <?=$o['payment_status']==='paid'?'good':($o['payment_status']==='reported'?'low':'')?>"><?=h(['unpaid'=>'Chưa thanh toán','reported'=>'Khách đã báo chuyển','paid'=>'Đã nhận tiền'][$o['payment_status']]??$o['payment_status'])?></span><?php if($o['payment_status']!=='paid'):?><form method="post" style="margin-top:6px"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="payment_confirm"><input type="hidden" name="id" value="<?=$o['id']?>"><button class="button button-sm">Xác nhận tiền</button></form><?php endif;?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="order_status"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><?php foreach(['pending','confirmed','preparing','shipping','completed','cancelled'] as $s):?><option value="<?=$s?>" <?=$s===$o['status']?'selected':''?>><?=h(admin_status($s))?></option><?php endforeach;?></select><button class="button button-sm">Lưu</button></form></td></tr><?php endforeach;?></table></section>
<?php elseif($tab==='customers'):?><section class="admin-card admin-table"><h2>Khách hàng và tài khoản chủ quán</h2><table><tr><th>Họ tên</th><th>Email</th><th>Điện thoại</th><th>Vai trò</th><th>Ngày sinh</th><th>Ngày tạo</th></tr><?php foreach($customers as $u):?><tr><td><?=h($u['fullname'])?></td><td><?=h($u['email'])?></td><td><?=h($u['phone'])?></td><td><span class="status-pill <?=$u['role']==='admin'?'good':''?>"><?=$u['role']==='admin'?'Chủ quán':'Khách hàng'?></span></td><td><?=h($u['birth_date']?date('d/m/Y',strtotime($u['birth_date'])):'—')?></td><td><?=h(date('d/m/Y',strtotime($u['created_at'])))?></td></tr><?php endforeach;?></table></section>
<?php else:?><section class="admin-card admin-table"><h2>Góp ý từ khách hàng</h2><table><tr><th>Thời gian</th><th>Người gửi</th><th>Email</th><th>Nội dung</th><th></th></tr><?php foreach($feedback as $f):?><tr><td><?=h(date('d/m/Y H:i',strtotime($f['created_at'])))?></td><td><?=h($f['name'])?></td><td><?=h($f['email'])?></td><td><?=nl2br(h($f['message']))?></td><td><form method="post" onsubmit="return confirm('Xóa góp ý này?')"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="feedback_delete"><input type="hidden" name="id" value="<?=$f['id']?>"><button class="button button-sm danger-button">Xóa</button></form></td></tr><?php endforeach;?></table></section><?php endif;?></main></body></html>

